package com.tripnest.repository; import com.tripnest.entity.WishlistItem; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface WishlistRepository extends JpaRepository<WishlistItem,Long>{List<WishlistItem> findByUserIdOrderByCreatedAtDesc(Long userId); Optional<WishlistItem> findByUserIdAndAccommodationId(Long userId,Long accommodationId); boolean existsByUserIdAndAccommodationId(Long userId,Long accommodationId); void deleteByUserIdAndAccommodationId(Long userId,Long accommodationId);}
